def transform(grid):
    from collections import Counter
    from math import gcd
    from functools import reduce

    counts = Counter(x for row in grid for x in row)
    common = {c for c, _ in counts.most_common(2)}
    points = [
        (r, c, grid[r][c])
        for r in range(len(grid))
        for c in range(len(grid[0]))
        if grid[r][c] not in common
    ]

    default = counts.most_common(1)[0][0]
    rows = sorted({r for r, _, _ in points})
    cols = sorted({c for _, c, _ in points})

    def spacing(values):
        diffs = [b - a for a, b in zip(values, values[1:]) if b > a]
        return reduce(gcd, diffs)

    row_step = spacing(rows)
    col_step = spacing(cols)
    row_nodes = list(range(rows[0], rows[-1] + 1, row_step))
    col_nodes = list(range(cols[0], cols[-1] + 1, col_step))

    output = [[default for _ in range(len(col_nodes) - 1)]
              for _ in range(len(row_nodes) - 1)]

    for i in range(len(row_nodes) - 1):
        for j in range(len(col_nodes) - 1):
            corners = [
                grid[row_nodes[i]][col_nodes[j]],
                grid[row_nodes[i]][col_nodes[j + 1]],
                grid[row_nodes[i + 1]][col_nodes[j]],
                grid[row_nodes[i + 1]][col_nodes[j + 1]],
            ]
            if corners[0] == corners[1] == corners[2] == corners[3]:
                if corners[0] not in common:
                    output[i][j] = corners[0]

    return output
